"""Working-group deliverables and local needs discovery, separate from the compute pilot."""
import csv,html,json,shutil
from pathlib import Path
E=html.escape

def build(root,generated,public,write):
    src=root/'site/compute-guide';g=json.loads((src/'working-group.json').read_text())
    # Preserve the existing compute calculator as an optional specialist tool.
    old=generated/'pages/needs.md';text=old.read_text().replace('# Scope your computing needs','# Optional compute estimate')
    text=text.replace('Estimate a research project or classroom workload before asking for resources.','Start with the <a href="needs.html">short needs brief</a>. Use this optional calculator only when you can estimate the workload; unknown technical quantities belong in the brief, not as invented numbers.')
    text=text.replace('<form class="needs-form" id="needsForm">','<form class="needs-form" id="needsForm"><input type="hidden" name="context" value="working-group">')
    text=text.replace('Greg hours / week for this scope','Potential technical-support hours / week').replace('Inside four total weekly hours for everything.','Scope-specific estimate; no college staffing capacity is assumed.')
    (generated/'pages/compute-estimator.md').write_text(text)
    # Keep the pilot's six-stage plan at a stable, explicit case-study address.
    shutil.copy2(generated/'pages/timeline.md',generated/'pages/pilot-stages.md')
    for name in ['pilot-plan','pilot-stages','access-request','budget','readiness','gpu-benchmark','classroom-assessment']:
        path=generated/'pages'/f'{name}.md';text=path.read_text();parts=text.split('\n',1)
        note='\n<div class="guide-note"><strong>Supporting compute pilot.</strong> These DS/MLIS proposals retain their own $0 cash and Greg’s four-hour weekly envelope. They are not college-wide capacity findings or the working group’s selected solution. <a href="deliverables.html">Return to working-group deliverables →</a></div>\n'
        path.write_text(parts[0]+'\n'+note+parts[1])
    intro='''Find a route for **College of Information Science research or teaching**. Filter by resource type and location, then open an entry for access, cost, limitations and dated sources.

[Download inventory CSV](computing-resource-inventory.csv) · [Develop a resource request](needs.html) · [Detailed platform references](supplemental.html#platform-references)

<div class="guide-note"><strong>Teaching on campus HPC:</strong> Puma class groups are permitted. Research and teaching share the PI allocation; queues and instructor-led support still need planning. <a href="report.html#campus-hpc-puma-classroom-access">Current allocation and limits →</a>.</div>

'''
    cards='<div data-directory><div class="guide-filter"><div class="guide-filter-grid"><label>Search inventory<input type="search" placeholder="Try college, AI Assistant, RSE, data or software"></label><label>Resource type<select><option value="all">All types</option>'+''.join('<option>'+E(c)+'</option>' for c in sorted({r['category'] for r in g['inventory']}))+'</select></label><label>Where available<select data-level-filter><option value="all">College, university and external</option><option>College</option><option>University</option><option>National / external</option></select></label></div><p role="status" aria-live="polite">'+str(len(g['inventory']))+' entries</p></div><div class="guide-directory">'
    for r in g['inventory']:
        source=' · '.join('<a href="'+E(u,quote=True)+'">Source '+str(i)+' ↗</a>' for i,u in enumerate(r['sources'],1))
        contact='<a href="'+E(r['contact_url'],quote=True)+'">'+E(r['contact'])+'</a>'
        cards+='<article class="guide-resource" data-resource data-level="'+E(r['level'])+'" data-category="'+E(r['category'])+'" id="'+E(r['id'])+'"><span class="guide-tag">'+E(r['level']+' · '+r['status'])+'</span><h3>'+E(r['name'])+'</h3><p>'+E(r['summary'])+'</p><p class="guide-contact"><strong>Contact:</strong> '+contact+'</p><details><summary>Access, costs, limitations and sources</summary><p><strong>Access:</strong> '+E(r['access'])+'</p><p><strong>Cost:</strong> '+E(r['cost'])+'</p><p><strong>Limits:</strong> '+E(r['limits'])+'</p><p><strong>Support:</strong> '+E(r['support'])+'</p><p><strong>Funding:</strong> '+E(r['funding'])+'</p><p>'+source+'</p><p><strong>Review basis:</strong> '+E(r['checked'])+'</p><p>'+E(r['verification'])+'</p><p><strong>Next:</strong> '+E(r['next_action'])+'</p></details></article>'
    write('inventory.md','Resource inventory',intro+cards+'</div><noscript><p>All entries are shown; filtering requires JavaScript.</p></noscript></div>\n\n## Keep the inventory useful\n\nConfirm access, owner, support window, funding, costs and limits before changing an entry to verified. Record missing resources as unknown, not unavailable. Use the [detailed platform directory](resource-library.html) for further comparisons.')
    phases=''
    for i,stage in enumerate(g['timeline'],1):
        phases+='<section class="guide-step"><div class="guide-step-num">'+str(i).zfill(2)+'</div><div><span class="guide-tag">'+E(stage['when'])+'</span><h2>'+E(stage['title'])+'</h2><p>'+E(stage['work'])+'</p><p><strong>Output:</strong> '+E(stage['output'])+'</p></div></section>'
    write('timeline.md','Working-group milestones','''The working group aims to draft **all four deliverables by the end of the Fall 2026 semester**, then refine and circulate them within the college **early in Spring 2027**. These are planning windows, not scheduled meetings or award dates.

'''+phases+'\n\n[Review deliverables](deliverables.html) · [Working-session guide](working-session.html)\n\n## Supporting compute-pilot sequence\n\nThe [separate CPU/GPU pilot stages](pilot-stages.html) depend on measurements, resource approval and classroom checks. Those gates do not define the working group’s semester deadlines.')
    path=generated/'pages/degree-options.md';path.write_text(path.read_text().replace('Nine Information Science degrees are in scope; cyber programs are excluded.','This earlier nine-degree comparison excludes cyber programs. The working group’s needs assessment covers the college and is not limited to this historical comparison.',1))
    # Existing history/resource pages remain valid, but no longer imply the pilot is
    # the entire college strategy.
    path=generated/'pages/resource-library.md';path.write_text(path.read_text().replace('# Find a resource','# Detailed platform directory',1).replace('Start with the work you need to do.','For college and university routes, start with the [working-group inventory](inventory.html). This detailed directory supports comparison and the compute case study. Start with the work you need to do.',1))
    fields=[('scope','Activity type',['Research','Instruction','Both research and instruction']),('stage','Current or anticipated',['Current need','Anticipated / emerging need']),('timing','When needed',['This semester','Early Spring 2027','Within 12 months','Not yet known']),('priority','Impact',['Work is blocked','Work is limited or difficult','Exploratory opportunity']),('data','Data involved',['Not yet known','Public / synthetic','Internal / student records','Restricted / regulated']),('budget','Funding position',['Not yet known','No funds identified','Existing resources identified; terms to verify','Confirmed funding; permitted use to verify'])]
    form='<form id="workingNeeds" class="needs-form"><label>What are you trying to do? <span class="guide-required">(required)</span><textarea name="activity" required maxlength="240" rows="2" placeholder="Describe an activity, not private project data or student information."></textarea></label><fieldset><legend>What resources would help? <span class="guide-required">(choose at least one)</span></legend><div class="working-checks">'
    types=['Hardware / compute','Software / models','Data / stewardship','Cloud / hosting','RSE / engineering','Technical support / training','Collaboration / shared services']
    form+=''.join('<label><input type="checkbox" name="resources" value="'+E(t)+'">'+E(t)+'</label>' for t in types)+'</div></fieldset><div class="needs-grid">'
    for key,label,choices in fields:form+='<label>'+label+'<select name="'+key+'">'+''.join('<option>'+E(t)+'</option>' for t in choices)+'</select></label>'
    form+='</div><fieldset><legend>What is getting in the way?</legend><div class="working-checks">'+''.join('<label><input type="checkbox" name="barriers" value="'+t+'">'+t+'</label>' for t in ['Access / eligibility','Capacity / reliability','Costs / funding','Software / data rights','Skills / onboarding','Staff / support time','Not yet known'])+'</div></fieldset>'
    form+='<details><summary>Optional detail · leave unknown quantities blank</summary><div class="needs-grid"><label>People or independent groups<input name="people" type="number" min="1" step="1" placeholder="Unknown"></label><label>Potential support hours/week<input name="hours" type="number" min="0" step="0.5" placeholder="Unknown"></label><label>Collaboration opportunity<select name="collaboration"><option>Not yet known</option><option>Within the college</option><option>Across the university</option><option>External partner / shared infrastructure</option></select></label></div>'
    for key,label,hint in [('requirements','Software, models, data or environment requirements','What must the workflow be able to do?'),('skills','RSE skills, technical support or training','Which tasks, expertise and support windows matter?'),('existing','Existing resource or workaround','What works, and where does it fall short?')]:form+='<label>'+label+'<textarea name="'+key+'" rows="2" maxlength="600" placeholder="'+hint+'"></textarea></label>'
    form+='</details><div class="guide-actions"><button class="guide-button" id="prepareWorkingBrief" type="submit" disabled>Prepare my brief</button><button class="needs-secondary" id="clearWorkingNeed" type="button">Clear fields</button></div></form><p id="workingError" class="needs-error" role="alert"></p><p id="workingStatus" role="status">Prepare a local brief. Sending it for Luna drafting or working-group review requires a separate action.</p><section id="workingResults" class="needs-results" hidden><h2 id="workingResultsTitle" tabindex="-1">Your local needs brief</h2><p id="workingDraftType" class="guide-tag"></p><h3 id="workingActivity"></h3><p id="workingSummary"></p><p id="workingTypes"></p><p><strong>Barriers:</strong> <span id="workingBarriers"></span></p><p id="workingCapacity"></p><h3>Next steps to review</h3><ul id="workingNext"></ul><div class="guide-actions"><button class="guide-button" type="button" data-working-export="text" disabled>Download brief</button><button class="needs-secondary" type="button" data-working-export="json" disabled>Download JSON</button></div><p>Download a copy for yourself, then review and submit below if you want the working group to see it.</p></section>'
    facts=[{k:r[k] for k in ['id','name','access','cost','contact','limits','source','checked']} for r in g['inventory']]
    request='<details class="guide-request"><summary>Develop a resource request</summary><p>This local template turns your brief into a reviewable request and adds documented resource routes. It does not use an LLM or decide eligibility. Candidate routes need owner confirmation.</p><label for="workingRequestText">Request draft</label><textarea id="workingRequestText" readonly rows="14"></textarea><div id="requestResourceFacts" data-resources="'+E(json.dumps(facts,ensure_ascii=False),quote=True)+'"></div><div class="guide-actions"><button type="button" class="needs-secondary" data-request-export="draft" disabled>Download request draft</button><button type="button" class="needs-secondary" data-request-export="prompt" disabled>Download AI drafting prompt</button><button type="button" class="needs-secondary" id="copyDraftingPrompt" disabled>Copy AI drafting prompt</button></div><p id="workingAIStatus" role="status"></p>'
    luna='<section id="lunaDrafting" data-endpoint="'+E(g.get('request_assistant',{}).get('endpoint',''),quote=True)+'"><h3>Optional Luna draft</h3><p>Use GPT-6 Luna to rewrite your brief and the dated resource facts into a short first draft. Review the result yourself. The local template above is always available.</p><label class="luna-consent"><input type="checkbox" id="lunaConsent" disabled> I reviewed my brief. It contains only public/synthetic, non-identifying information, and I agree to send it and the listed resource facts through the drafting service to OpenAI.</label><p>Limited pilot: five attempts per network each day. Your local template remains available.</p><details><summary>Usage limits and data handling</summary><p>Shared allowance: 20 attempts/day, 200/month, up to 1,000 output tokens each. Failed attempts count; there are no automatic retries. The application keeps allowance counters and rotating network hashes, not your brief or generated text. OpenAI processes the requested text under its API terms; store:false is requested, not a zero-retention guarantee.</p></details><button type="button" class="guide-button" id="generateLunaDraft" aria-controls="lunaResult" aria-describedby="lunaStatus" disabled>Draft with Luna</button><p id="lunaStatus" role="status" aria-live="polite"></p><div id="lunaResult" hidden><label for="lunaDraftText">AI-assisted draft — review and edit before sharing</label><textarea id="lunaDraftText" rows="16"></textarea><button type="button" class="needs-secondary" id="downloadLunaDraft" disabled>Download reviewed draft</button></div></section>'
    campus='<p><strong>Campus alternative:</strong> copy or download the public/synthetic prompt and paste it into <a href="https://ai-assistant.responsibleai.arizona.edu/" target="_blank" rel="noopener">Arizona AI Assistant ↗</a>. Wolfgang Jentner at ORAI, via Greg Chism, reports that AI Verde will transition to this service with $200/month of Bedrock credit available; credit scope, eligibility and renewal terms need confirmation. <a href="campus-ai.html">Transition and model pricing →</a>. <a href="https://responsibleai.arizona.edu/tools-support/u-gen-ai">U of A GenAI</a> is another documented NetID route. The site does not connect to either campus service.</p>'
    request=request+luna+campus+'</details>'
    submission='<section id="requestSubmission" data-endpoint="https://infosci-compute-drafter.vercel.app/api/requests"><h3>Submit a completed brief</h3><p>A small pilot queue for <strong>Barney Maccabe and Greg Chism</strong>. Submission is optional and does not use AI. Use your own public/synthetic, non-sensitive brief; no student records, credentials, confidential research or attachments.</p><p id="submissionEligibility"></p><div class="guide-actions"><button class="needs-secondary" type="button" id="useLocalSubmission">Use local request draft</button><button class="needs-secondary" type="button" id="useLunaSubmission">Use reviewed Luna draft</button></div><label for="submissionText">Completed brief · review and edit before submitting</label><textarea id="submissionText" rows="12" minlength="40" maxlength="14000"></textarea><div class="needs-grid"><label>Name (optional)<input id="submissionName" maxlength="100" autocomplete="name"></label><label>University email (required)<input id="submissionEmail" type="email" required maxlength="120" pattern="[^@ ]+@arizona\\.edu" autocomplete="email" placeholder="you@arizona.edu"></label></div><div class="submission-trap" aria-hidden="true"><label>Leave empty<input id="submissionWebsite" type="text" tabindex="-1" autocomplete="off"></label></div><label class="luna-consent"><input id="submissionConsent" type="checkbox" disabled> I reviewed this text. Apart from my contact details, it contains only public/synthetic, non-sensitive information. I agree to store it in the private pilot queue for Barney and Greg to review.</label><details><summary>Storage, limits and what happens next</summary><p>Your contact details, brief and review notes are stored privately on the working group’s existing Vercel hosting, outside university Microsoft 365. This is a limited pilot, not university sign-in or an approved channel for sensitive data. Contact addresses are self-reported. Only reviewers with the shared passphrase can access the queue. They may export it or delete requests; there is no automatic deletion schedule. Contact a point person with your reference to request removal. Submission does not send your contact details or brief to Luna/OpenAI, notify reviewers by email, submit an ACCESS application or guarantee support.</p><p>Limits: three submissions per network/day, 20 shared/day, 100/month and 100 stored requests. A full queue pauses submissions. There are no automatic retries; keep your download. Reviewers can <a href="https://infosci-compute-drafter.vercel.app/review/" target="_blank" rel="noopener">open the private queue ↗</a>.</p></details><button id="submitWorkingRequest" type="button" class="guide-button" disabled>Submit for working-group review</button><p id="submissionStatus" role="status" aria-live="polite"></p></section>'
    request='<p class="guide-note"><strong>Campus CPU/GPU route:</strong> Puma permits class groups. The published 150,000 CPU core-hours per PI/month is shared by research and classes; GPU jobs use the same pool. It is not a class reservation. Queues may delay jobs; instructors support students. <a href="report.html#campus-hpc-puma-classroom-access">Allocation, queue and support limits →</a></p>'+request
    form=form.replace('</section>',request+submission+'</section>')
    write('needs.md','Resource request tool','''<span id="describe-a-computing-resource-need"></span>

Describe the **research or teaching activity**, the resources that would help and the barriers. You do not need a GPU-hour estimate or a budget. Unknown quantities can stay unknown.

**Local by default.** Preparing a brief does not submit it to the working group. Optional Luna drafting sends a reviewed public/synthetic brief for AI processing only with your consent. Keep student records and confidential research out of this public tool. A separate, optional submission step stores only your reviewed brief and the contact details you provide in the private pilot queue.

<div class="guide-actions"><button class="needs-secondary" type="button" data-working-example="data">Try a software/data example</button><button class="needs-secondary" type="button" data-working-example="classroom">Try a classroom example</button></div>

'''+form+'''

## If technical sizing would help

Use the [optional compute estimator](compute-estimator.html) for CPU/GPU, concurrency and storage assumptions. It is one attachment to the need, not a requirement for participating. Measured demand and provider access still need confirmation.

<noscript><p class="guide-note">Local brief generation needs JavaScript. You can still use the <a href="computing-needs-register.csv">blank needs register</a> to record the activity, resource types, barriers, timing and unknowns, then share it through the agreed university channel.</p></noscript>

[How needs will be assessed](needs-assessment.html) · [Working-group deliverables](deliverables.html)''')
    # Downloadable draft artifacts. No respondent or internal personnel data.
    (public/'ai-working-group.json').write_text(json.dumps(g,indent=2)+'\n')
    def csvfile(name,keys,rows):
        with (public/name).open('w',newline='') as f:
            writer=csv.DictWriter(f,fieldnames=keys,lineterminator='\n');writer.writeheader();writer.writerows(rows)
    inventory_rows=[{**r,'sources':json.dumps(r['sources'],ensure_ascii=False)} for r in g['inventory']]
    csvfile('ai-resource-inventory.csv',list(inventory_rows[0]),inventory_rows)
    csvfile('ai-needs-register.csv',['need_id','activity','scope','current_or_anticipated','resource_types','barriers','people_or_groups','needed_by','impact','requirements','skills_support','potential_support_hours_week','funding_status','existing_workaround','evidence_basis','review_status'],[])
    csvfile('ai-recommendations-template.csv',['action','college_or_university','problem_evidence','users_served','owner_role','dependencies','effort_hours','recurring_obligations','funding_status','success_measure','review_point','decision_status'],[])
    packet=g['college']+'\n'+g['title']+'\nDRAFT WORKING PACKET | October 19, 2026\nPoint people: Barney Maccabe | maccabe@arizona.edu; Greg Chism, Faculty Director of Instructional Computing | gchism@arizona.edu\n\n'+g['scope']+'\n'+g['charter_status']+'\n\nOBJECTIVES\n'+'\n'.join(g['objectives'])+'\n\nDELIVERABLES\n'
    for r in g['deliverables']:packet+='\n'+r['name']+' | '+r['status']+'\nPreliminary draft: '+r['draft']+'\n'+r['url']+'\n'
    packet+='\nMILESTONES\n'
    for r in g['timeline']:packet+='\n'+r['when']+' | '+r['title']+'\n'+r['work']+'\nOutput: '+r['output']+'\n'
    packet+='\nUSE AND REVIEW\nThe resource tool offers explicit submission of a reviewed public/synthetic brief and contact details to a private pilot queue for Barney and Greg. Optional Luna drafting is separate and does not persist briefs in the drafting service. The queue stores submissions and review notes until reviewers delete them; it is outside university Microsoft 365 and is not for sensitive data. Agree deliverable owner roles and the review process. No group endorsements, college-wide needs totals, staff availability or funding are assumed. The separate pilot retains its own zero-cash/four-hour constraints.\n'
    packet+='\nSEEDED RESOURCE INVENTORY\n'
    for item in g['inventory']:packet+='\n'+item['name']+' | '+item['level']+' | '+item['status']+'\nAccess: '+item['access']+'\nCost: '+item['cost']+'\nContact: '+item['contact']+' | '+item['contact_url']+'\nSupport: '+item['support']+'\nLimits: '+item['limits']+'\nFunding: '+item['funding']+'\nSources: '+' | '.join(item['sources'])+'\nReview: '+item['checked']+'\n'+item['verification']+'\n'
    for name in ['needs-assessment','primers','approaches','drafting-notes','campus-ai','recommendations','working-session']:packet+='\n'+(src/'pages'/f'{name}.md').read_text()+'\n'
    packet=packet.rstrip()+'\n'
    (public/'ai-working-group-packet.txt').write_text(packet)
    for old,new in [('ai-resource-inventory.csv','computing-resource-inventory.csv'),('ai-working-group.json','computing-working-group.json'),('ai-needs-register.csv','computing-needs-register.csv'),('ai-recommendations-template.csv','computing-recommendations-template.csv'),('ai-working-group-packet.txt','computing-working-group-packet.txt')]:shutil.copy2(public/old,public/new)
    report=(public/'research-and-sources.txt').read_text()+'\n\nCOMPUTING RESOURCES WORKING GROUP | October 19, 2026\n'+packet+'\nCAMPUS INVENTORY SOURCES\n'+'\n'.join(r['name']+' | '+' | '.join(r['sources'])+' | '+r['checked'] for r in g['inventory'] if r['level']!='National / external')+'\n'
    (public/'research-and-sources.txt').write_text(report);(root/'output/education-compute/research-and-sources.txt').write_text(report)
    evidence=generated/'pages/evidence.md';evidence.write_text(evidence.read_text().replace('181 primary-source and verification records.','181 compute-history source and verification records. Current working-group campus sources are linked in the [resource inventory](inventory.html).',1))
